() => {
  // Get all text from the main content area
  const main = document.querySelector('main');
  if (!main) return { error: 'no main' };
  // Find content divs with substantial text
  const all = Array.from(main.querySelectorAll('div, section, article')).filter(el => {
    const t = el.innerText || '';
    return t.length > 200 && t.length < 50000 && el.children.length < 50;
  }).map(el => ({ className: el.className, text: el.innerText.slice(0, 3000) }));
  const menus = Array.from(document.querySelectorAll('[role="menuitem"]')).map(el => el.textContent?.trim());
  return { menus, samples: all.slice(0, 5), fullText: main.innerText.slice(0, 15000) };
}

