async (page) => {
  await page.getByRole('menuitem', { name: '卖家自研插件' }).click();
  await page.waitForTimeout(2000);
  // Expand any submenu
  const menus = await page.evaluate(() => Array.from(document.querySelectorAll('[role="menuitem"]')).map(el => el.textContent?.trim()));
  // Get all submenu items under 卖家自研插件 if expanded
  const text = await page.evaluate(() => {
    const el = document.querySelector('[class*="content___"]') || document.querySelector('main');
    return el ? el.innerText : '';
  });
  return { menus, textLength: text.length, text: text.slice(0, 30000) };
}

async (page) => {
  const results = {};
  for (const name of ['如何打包插件', '上架卖家自研插件', '如何使用插件', '谷歌插件开发调试教程']) {
    await page.getByRole('menuitem', { name }).click();
    await page.waitForTimeout(1500);
    const text = await page.evaluate(() => {
      // Prefer the article content area
      const candidates = Array.from(document.querySelectorAll('[class*="content___"], article, .markdown-body, [class*="doc"]'));
      let best = '';
      for (const el of candidates) {
        const t = el.innerText || '';
        if (t.length > best.length && t.length < 100000) best = t;
      }
      if (!best) best = document.querySelector('main')?.innerText || '';
      return best;
    });
    results[name] = text.slice(0, 20000);
  }
  return results;
}

