:root {
  --bg: #0f1419;
  --card: #1a222c;
  --text: #e7ecf1;
  --muted: #8b9aab;
  --primary: #3b82f6;
  --primary-hover: #2563eb;
  --ok: #22c55e;
  --warn: #eab308;
  --err: #ef4444;
  --border: #2a3542;
  --radius: 10px;
  font-family: "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  width: 360px;
  background: var(--bg);
  color: var(--text);
  font-size: 13px;
  line-height: 1.45;
}

.header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 14px 14px 8px;
}

h1 {
  margin: 0;
  font-size: 16px;
  font-weight: 650;
}

.sub {
  margin: 2px 0 0;
  color: var(--muted);
  font-size: 11px;
}

.link {
  color: var(--primary);
  text-decoration: none;
  font-size: 12px;
  padding-top: 2px;
}

.card {
  margin: 8px 12px;
  padding: 12px;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
}

.card.compact {
  padding: 10px 12px;
}

.row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 8px;
}

.row.between {
  margin-bottom: 6px;
}

.row.check {
  justify-content: flex-start;
}

.row span {
  color: var(--muted);
  white-space: nowrap;
}

select,
input[type="date"],
input[type="text"],
input[type="password"],
input[type="number"],
textarea {
  flex: 1;
  min-width: 0;
  background: var(--bg);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 6px 8px;
  font-size: 12px;
}

.hint {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 11px;
}

.actions {
  display: flex;
  gap: 8px;
  padding: 4px 12px 8px;
}

.btn {
  appearance: none;
  border: 1px solid var(--border);
  background: var(--card);
  color: var(--text);
  border-radius: 8px;
  padding: 8px 12px;
  font-size: 13px;
  cursor: pointer;
  flex: 1;
}

.btn:hover {
  border-color: #3d4d60;
}

.btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.btn.primary {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
  font-weight: 600;
}

.btn.primary:hover {
  background: var(--primary-hover);
}

.btn.tiny {
  flex: 0;
  padding: 4px 8px;
  font-size: 11px;
}

.status-line {
  display: flex;
  align-items: center;
  gap: 8px;
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--muted);
  flex-shrink: 0;
}

.dot.ok {
  background: var(--ok);
}
.dot.warn {
  background: var(--warn);
}
.dot.err {
  background: var(--err);
}
.dot.busy {
  background: var(--primary);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.25);
}

.preview {
  margin: 10px 0 0;
  max-height: 180px;
  overflow: auto;
  background: var(--bg);
  border-radius: 6px;
  padding: 8px;
  font-size: 11px;
  color: #c5d0db;
  white-space: pre-wrap;
  word-break: break-all;
}

.log-list {
  list-style: none;
  margin: 0;
  padding: 0;
  max-height: 120px;
  overflow: auto;
}

.log-list li {
  padding: 6px 0;
  border-bottom: 1px solid var(--border);
  font-size: 11px;
  color: var(--muted);
}

.log-list li .lv {
  display: inline-block;
  min-width: 42px;
  color: var(--text);
}

.log-list li.error .lv {
  color: var(--err);
}
.log-list li.success .lv {
  color: var(--ok);
}
.log-list li.warn .lv {
  color: var(--warn);
}

